INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28501, '1 Thessalonians 5:13', '1 Thessalonians', 5, 13, '&nbsp;او د هغوئ د کار په سبب په ډېره مينه د هغوئ ډېر عزت کوئ، او په خپل مينځ کښې په امن و امان ژوند تېروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28502, '1 Thessalonians 5:14', '1 Thessalonians', 5, 14, '&nbsp;او اے عزيزانو، مونږ په تاسو زور راوړُو چې سستو خلقو ته نصيحت کوئ، بې‌زړۀ خلقو له ډاډګيرنه ورکوئ، د کمزورو مدد کوئ، او ټولو سره د صبر معامله کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28503, '1 Thessalonians 5:15', '1 Thessalonians', 5, 15, '&nbsp;ګورئ چې څوک هم په تاسو کښې د بدۍ په بدله کښې بدى ونۀ کړى بلکې همېشه کوشش کوئ چې د يو بل سره او د ټولو سره نېکى کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28504, '1 Thessalonians 5:16', '1 Thessalonians', 5, 16, '&nbsp;او همېشه خوشحاله اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28505, '1 Thessalonians 5:17', '1 Thessalonians', 5, 17, '&nbsp;په دُعا کښې ناغه مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28506, '1 Thessalonians 5:18', '1 Thessalonians', 5, 18, '&nbsp;په هر حال کښې شُکر کوئ ځکه چې دا په عيسىٰ مسيح کښې ستاسو دپاره د خُدائ پاک رضا ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28507, '1 Thessalonians 5:19', '1 Thessalonians', 5, 19, '&nbsp;د روحُ القُدس بل شوے اور مۀ مړ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28508, '1 Thessalonians 5:20', '1 Thessalonians', 5, 20, '&nbsp;د چا پېشګويۍ ته سپک نظر مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28509, '1 Thessalonians 5:21', '1 Thessalonians', 5, 21, '&nbsp;خو ټولې پېشګويانې وآزمايئ او چې کومې ښې وى هغه راټينګوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28510, '1 Thessalonians 5:22', '1 Thessalonians', 5, 22, '&nbsp;د هر قِسم بد کار نه ځان ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28511, '1 Thessalonians 5:23', '1 Thessalonians', 5, 23, '&nbsp;خُدائ پاک چې د سلامتۍ سرچينه دے هغه دې تاسو په خپله پوره پاک کړى، او ستاسو ټول ژوند دې زمونږ د مالِک عيسىٰ مسيح تر راتلو پورې پوره بې‌عېبه وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28512, '1 Thessalonians 5:24', '1 Thessalonians', 5, 24, '&nbsp;څوک چې ستاسو رابلونکے دے هغه وفادار دے او هغه به هم دغه شان وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28513, '1 Thessalonians 5:25', '1 Thessalonians', 5, 25, '&nbsp;اے وروڼو او خوېندو، زمونږ دپاره دُعا کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28514, '1 Thessalonians 5:26', '1 Thessalonians', 5, 26, '&nbsp;زما د خوا نه ټولو ايماندارانو ته په پاکې مينې سره سلام ووايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28515, '1 Thessalonians 5:27', '1 Thessalonians', 5, 27, '&nbsp;زۀ تاسو له د مالِک په نوم حُکم درکوم چې دا خط ټولو وروڼو او خوېندو ته واوروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28516, '1 Thessalonians 5:28', '1 Thessalonians', 5, 28, '&nbsp;زمونږ د مالِک عيسىٰ مسيح فضل دې تاسو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28517, '2 Thessalonians 1:1', '2 Thessalonians', 1, 1, '&nbsp;د پولوس او سيلوانوس او د تيموتيوس د طرف نه، د تِسالونيکيانو د جماعت دپاره خط چې زمونږ د خُدائ پلار او د مالِک عيسىٰ مسيح دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28518, '2 Thessalonians 1:2', '2 Thessalonians', 1, 2, '&nbsp;په تاسو دې زمونږ د خُدائ پلار او د مالِک عيسىٰ مسيح د طرف نه فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28519, '2 Thessalonians 1:3', '2 Thessalonians', 1, 3, '&nbsp;اے ګرانو وروڼو او خوېندو، ستاسو په حقله مونږ له هر وخت د خُدائ پاک شُکر ويستل په کار دى، او دا مناسب دى ځکه چې ستاسو ايمان نور نور زياتيږى او ستاسو د هر يو مينه د يو بل سره نوره هم زياتيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28520, '2 Thessalonians 1:4', '2 Thessalonians', 1, 4, '&nbsp;په دې وجه مونږ په خپله د خُدائ پاک په جماعتونو کښې په تاسو فخر کوُو، د هغه ظلم او تکليفونو دپاره چې تاسو يې زغمئ په هغو ټولو کښې ستاسو قائموالے او ايمان ظاهريږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28521, '2 Thessalonians 1:5', '2 Thessalonians', 1, 5, '&nbsp;دا د خُدائ پاک د رښتونى عدالت ثبوت دے د دې دپاره چې تاسو د خُدائ پاک د هغه بادشاهۍ لائق کړى چې د کوم دپاره تاسو تکليفونه هم زغمئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28522, '2 Thessalonians 1:6', '2 Thessalonians', 1, 6, '&nbsp;ځکه چې خُدائ پاک اِنصاف کوونکے دے، هغه به هغوئ نه ستاسو بدل واخلى څوک چې تاسو له تکليف درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28523, '2 Thessalonians 1:7', '2 Thessalonians', 1, 7, '&nbsp;او خُدائ پاک به تاسو له آرام درکړى تاسو څوک چې په مصيبت کښې راګېر يئ او هم مونږ له چې کله مالِک عيسىٰ د آسمان نه راڅرګند شى. او د خپلو قوتناکو فرښتو سره راشى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28524, '2 Thessalonians 1:8', '2 Thessalonians', 1, 8, '&nbsp;او په شُغله ناک اور سره به هغه هغوئ له سزا ورکړى څوک چې خُدائ پاک نۀ پېژنى او زمونږ د مالِک عيسىٰ مسيح زيرے نۀ منى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28525, '2 Thessalonians 1:9', '2 Thessalonians', 1, 9, '&nbsp;هغوئ ته به د ابدى تباهۍ سزا مِلاو شى او د مالِک د حضور او د جلالى قدرت نه به هغوئ جدا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28526, '2 Thessalonians 1:10', '2 Thessalonians', 1, 10, '&nbsp;په هم هغه ورځ کله چې هغه راشى نو ټول مقدسين به هغۀ له جلال ورکړى او د هغۀ حمد و ثنا به ووائى. په هغوئ کښې به تاسو هم شامل يئ ځکه چې تاسو زمونږ په ګواهۍ ايمان راوړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28527, '2 Thessalonians 1:11', '2 Thessalonians', 1, 11, '&nbsp;هم په دې وجه مونږ ستاسو دپاره همېشه دُعا کوُو چې زمونږ خُدائ پاک دې تاسو د خپلې بلنې جوګه کړى، او ستاسو د نېکۍ هر يو خواهش او د ايمان هر يو کار دې په خپل قدرت سره پوره کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28528, '2 Thessalonians 1:12', '2 Thessalonians', 1, 12, '&nbsp;نو بيا به زمونږ د مالِک عيسىٰ نوم ستاسو د چال چلن په وجه جلال ومومى او تاسو به هم ورسره جلال ومومئ. دا هر څۀ زمونږ د خُدائ پاک او د مالِک عيسىٰ مسيح د فضل په مطابق وشو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28529, '2 Thessalonians 2:1', '2 Thessalonians', 2, 1, '&nbsp;نو اوس اے وروڼو او خوېندو، مونږ د خپل مالِک عيسىٰ مسيح د راتلو او د هغۀ سره زمونږ د راغونډېدلو په حقله تاسو ته خواست کوُو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28530, '2 Thessalonians 2:2', '2 Thessalonians', 2, 2, '&nbsp;چې تاسو زر پرېشانه نۀ شئ او نۀ دې ستاسو وار خطا شى کۀ څوک درته د رويا نه يا د کلام نه او يا زمونږ نه د خط په وسيله ووائى چې د مالِک خُدائ د قيامت ورځ خو راغلې ده، نو تاسو په داسې خبرو باور مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28531, '2 Thessalonians 2:3', '2 Thessalonians', 2, 3, '&nbsp;څوک دې تاسو په هيڅ طريقه دوکه نۀ کړى. ځکه چې هغه ورځ به تر هغې نۀ راځى ترڅو پورې چې بغاوت شروع نۀ شى او بيا بې‌شرعې کس څرګند نۀ شى، څوک چې د هلاکېدو دپاره مقرر شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28532, '2 Thessalonians 2:4', '2 Thessalonians', 2, 4, '&nbsp;هغه به د هر يو معبود او د عبادت د هر يو څيز مخالفت کوى او خپل ځان به ترې نه اوچت ګڼى. او هغه به د خُدائ په کور کښې کښېنى او د خُدايئ دعوىٰ به وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28533, '2 Thessalonians 2:5', '2 Thessalonians', 2, 5, '&nbsp;ولې تاسو ته ياد نۀ دى چې کله زۀ لا تاسو سره وم نو تاسو ته مې دا خبرې کړې وې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28534, '2 Thessalonians 2:6', '2 Thessalonians', 2, 6, '&nbsp;او اوس چې کوم څيز هغه ايساروى تاسو د هغې نه خبر يئ، تر څو چې هغه په خپل مقرر وخت څرګند شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28535, '2 Thessalonians 2:7', '2 Thessalonians', 2, 7, '&nbsp;ځکه چې د بې‌شرعې پټ طاقتونه کار کښې لګيا دى، خو دا به تر هغې کار کوى ترڅو چې د دې ايساروونکے لارې نه لرې نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28536, '2 Thessalonians 2:8', '2 Thessalonians', 2, 8, '&nbsp;او بيا به هغه بې‌دينه کس راڅرګند شى، او مالِک عيسىٰ به يې د خپلې خولې په پوکى تباه کړى، او د خپلو راتلو په جلال به يې تباه کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28537, '2 Thessalonians 2:9', '2 Thessalonians', 2, 9, '&nbsp;د دې بې‌دينه کس راتلل او کارونه به د شېطان په طاقت وى، څوک چې به هر قسم قدرت، د دروغو نښې او معجزې به ښکاره کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28538, '2 Thessalonians 2:10', '2 Thessalonians', 2, 10, '&nbsp;او هغوئ څوک چې هلاکېدونکى دى نو هغه به يې په خپل شرارت سره دوکه کړى. ځکه چې نۀ هغوئ د حق سره مينه کوله او نۀ يې هغه حق منلو کوم چې هغوئ ته خلاصون ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28539, '2 Thessalonians 2:11', '2 Thessalonians', 2, 11, '&nbsp;په دې وجه به خُدائ پاک هغوئ سخت بې‌لارې کړى او هغوئ به په دروغو يقين ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28540, '2 Thessalonians 2:12', '2 Thessalonians', 2, 12, '&nbsp;نو هغوئ څوک چې په حق يقين نۀ کوى بلکې د بدۍ په کارونو خوشحاليږى، هغوئ ټول به سزا ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28541, '2 Thessalonians 2:13', '2 Thessalonians', 2, 13, '&nbsp;خو په مالِک کښې زمونږ ګرانو وروڼو او خوېندو، مونږ ته همېشه ستاسو په حقله د خُدائ پاک شُکر کول په کار دى، ځکه چې تاسو د خُدائ پاک اولنۍ د خلاصون غوره کړے شوې مېوه يئ کوم خلاصون چې د روحُ القُدس په وسيله ملاويږى او هغه تاسو پاکوى چې په حق ايمان راوړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28542, '2 Thessalonians 2:14', '2 Thessalonians', 2, 14, '&nbsp;د دې مقصد دپاره هغۀ تاسو زمونږ د زيرى په وسيله راوبللئ نو چې تاسو زمونږ د مالِک عيسىٰ مسيح په جلال کښې شامل شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28543, '2 Thessalonians 2:15', '2 Thessalonians', 2, 15, '&nbsp;نو بيا اے وروڼو او خوېندو، مضبوط شئ او د کوم دستور چې بيا تاسو زمونږ د خولې نه يا مو د خط په وسيله تعليم حاصل کړے دے تاسو په هغې قائم پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28544, '2 Thessalonians 2:16', '2 Thessalonians', 2, 16, '&nbsp;اوس دې زمونږ مالِک عيسىٰ مسيح په خپله او زمونږ خُدائ پلار چا چې مونږ سره مينه وکړه او مونږ ته يې د فضل په وسيله ابدى تسلى او ښۀ اُميد راکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28545, '2 Thessalonians 2:17', '2 Thessalonians', 2, 17, '&nbsp;هغه دې ستاسو زړونو ته ډاډګيرنه درکړى او په هر نېک کار او خبرو اترو کښې دې تاسو مضبوط کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28546, '2 Thessalonians 3:1', '2 Thessalonians', 3, 1, '&nbsp;نو اے وروڼو او خوېندو، زمونږ دپاره دُعا کوئ چې د مالِک کلام زر خور شى او هر چرته داسې عزت حاصل کړى څنګه چې يې ستاسو په مينځ کښې حاصل کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28547, '2 Thessalonians 3:2', '2 Thessalonians', 3, 2, '&nbsp;او دُعا کوئ چې مونږ د بدو او خرابو خلقو نه بچ پاتې شُو ځکه چې ټول ايماندار نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28548, '2 Thessalonians 3:3', '2 Thessalonians', 3, 3, '&nbsp;خو مالِک وفادار دے، هغه به تاسو تکړه کړى او هغه به تاسو د شېطان نه بچ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28549, '2 Thessalonians 3:4', '2 Thessalonians', 3, 4, '&nbsp;او ستاسو په حقله زمونږ په مالِک اعتماد دے چې تاسو اوس هم هغه کارونه کوئ او بيا به يې هم کوئ د کوم چې مونږ درته حکم کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28550, '2 Thessalonians 3:5', '2 Thessalonians', 3, 5, '&nbsp;مالِک دې ستاسو زړونه د خُدائ پاک په مينه او د مسيح په صبر معمور کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28551, '2 Thessalonians 3:6', '2 Thessalonians', 3, 6, '&nbsp;اے عزيزانو، مونږ تاسو ته د خپل مالِک عيسىٰ مسيح په نوم حکم درکوو چې د هغه ايماندارانو سره تعلق مۀ ساتئ څوک چې ناراسته دى او په هغه تعليم عمل نۀ کوى چې مونږ هغوئ له ورکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28552, '2 Thessalonians 3:7', '2 Thessalonians', 3, 7, '&nbsp;ځکه چې تاسو په خپله خبر يئ چې تاسو ته زمونږ په نقش قدم ژوند تېرول په کار دى او کله چې مونږ تاسو سره وُو نو مونږ ناراسته نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28553, '2 Thessalonians 3:8', '2 Thessalonians', 3, 8, '&nbsp;او مونږ د چا روټۍ مفت ونۀ خوړه بلکې شپه او ورځ مو خوارى او مشقت سره کار کولو نو چې مونږ په تاسو کښې په چا بوج جوړ نۀ شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28554, '2 Thessalonians 3:9', '2 Thessalonians', 3, 9, '&nbsp;مونږ ته دا حق حاصل وو چې تاسو نه روټۍ وغواړو بلکې مونږ داسې ونۀ کړل او په کار کولو مونږ خپل ځان تاسو ته نمونه وګرځولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28555, '2 Thessalonians 3:10', '2 Thessalonians', 3, 10, '&nbsp;ځکه کله چې مونږ تاسو سره وُو نو مونږ هغه وخت تاسو ته دا حکم درکړو چې څوک کار کول نۀ غواړى نو هغه دې خوراک هم نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28556, '2 Thessalonians 3:11', '2 Thessalonians', 3, 11, '&nbsp;خو مونږ اورو چې په تاسو کښې ځينې ناراسته ژوند تېروى او هيڅ کار نۀ کوى او بلکې د نورو په کار کښې هم ګوتې وهى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28557, '2 Thessalonians 3:12', '2 Thessalonians', 3, 12, '&nbsp;نو داسې کسانو له مونږ د مالِک عيسىٰ مسيح په نوم حکم ورکوو او ورته دا وايو چې په آرام سره دې خپل کار کوى او خپله روټۍ دې په خپله ګټى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28558, '2 Thessalonians 3:13', '2 Thessalonians', 3, 13, '&nbsp;زما وروڼو او خوېندو، تاسو په نېک کار کښې همت مۀ بائيلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28559, '2 Thessalonians 3:14', '2 Thessalonians', 3, 14, '&nbsp;او کۀ څوک په دې خط کښې زمونږ وئيلے شوې خبرې نۀ منى نو هغه په نظر کښې ساتئ او د هغوئ سره تعلق مۀ ساتئ چې هغوئ وشرميږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28560, '2 Thessalonians 3:15', '2 Thessalonians', 3, 15, '&nbsp;خو هغوئ دشمنان مۀ ګڼئ بلکې د ايماندارانو وروڼو په شان نصيحت ورته کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28561, '2 Thessalonians 3:16', '2 Thessalonians', 3, 16, '&nbsp;اوس مالِک چې د سلامتۍ سرچينه دے په خپله دې تاسو ته هر وخت او په هر حال کښې سلامتى درکړى. مالِک دې تاسو ټولو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28562, '2 Thessalonians 3:17', '2 Thessalonians', 3, 17, '&nbsp;زۀ پولوس په خپل لاس درته دا سلامونه ليکم او زما په ټولو خطونو کښې د ثبوت دپاره دا زما د ليکلو نښه او طريقه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28563, '2 Thessalonians 3:18', '2 Thessalonians', 3, 18, '&nbsp;زمونږ د مالِک عيسىٰ مسيح فضل دې تاسو ټولو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28564, '1 Timothy 1:1', '1 Timothy', 1, 1, '&nbsp;د پولوس د طرف نه خط چې د خلاصوونکى خُدائ پاک او د عيسىٰ مسيح په حکم څوک چې مونږ له اُميد راکوى، د عيسىٰ مسيح رسول دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28565, '1 Timothy 1:2', '1 Timothy', 1, 2, '&nbsp;تيموتيوس ته چې په ايمان کښې زما وفادار زوئ دے. په تا دې د خُدائ پلار او زمونږ د مالِک عيسىٰ مسيح د طرف نه فضل، رحم او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28566, '1 Timothy 1:3', '1 Timothy', 1, 3, '&nbsp;لکه څنګه چې مِکدونيه ته د تلو په وخت ما په تا زور راوړو چې په اِفِسوس کښې پاتې شه او ځينې کسانو له هدايت ورکړه چې غلط تعليم ورنۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28567, '1 Timothy 1:4', '1 Timothy', 1, 4, '&nbsp;تاسو خلقو ته ووايئ چې خپل وخت د خپل پلار نيکۀ د دروغژنو نسب‌نامو په قيصو مۀ ضائع کوئ، کوم چې صرف د خلقو په مينځ کښې د بحث مباحثى سبب کيږى. داسې بحثونه د خُدائ په خدمت کولو کښې بې‌فائدې دى، خو دا کارونه په هغه وخت کښې ممکن دى چې تاسو په خُدائ پاک ايمان ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28568, '1 Timothy 1:5', '1 Timothy', 1, 5, '&nbsp;خو زمونږ د داسې هدايت ورکولو نه مقصد هغه مينه ده چې په پاک زړۀ او نېک نيت او رښتينى ايمان سره پېدا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28569, '1 Timothy 1:6', '1 Timothy', 1, 6, '&nbsp;خو ځينى خلقو د دې نه مخ واړولو او ګمراه شول او په عبثو خبرو پسې ګرځېدل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28570, '1 Timothy 1:7', '1 Timothy', 1, 7, '&nbsp;دوئ غواړى چې د شريعت اُستاذان جوړ شى، خو هغوئ په خپلو خبرو نۀ پوهيږى چې څۀ وائى خو بيا هم ډېر ډاډه لګيا وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28571, '1 Timothy 1:8', '1 Timothy', 1, 8, '&nbsp;مونږ پوهيږو چې شريعت ښۀ دے، خو چې څوک شريعت په قانونى طور استعمال کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28572, '1 Timothy 1:9', '1 Timothy', 1, 9, '&nbsp;خو په کار دے چې مونږ په دې پوهه شُو چې شريعت د نېکانو دپاره نۀ دے بلکې د بې‌شريعته او نافرمانو خلقو دپاره، د بې‌دينه او ګناهګارو دپاره، او د دين سپک کوونکو دپاره، او د هغوئ دپاره دے چې پلار او مور يې وژلى وى، د قاتلانو دپاره،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28573, '1 Timothy 1:10', '1 Timothy', 1, 10, '&nbsp;د حرامکارانو او د بچه بازانو، د اغوا کارو، د دروغژنو او د دروغو قَسم خوړونکو او د دې نه علاوه د رښتينى تعليم د مخالفينو دپاره دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28574, '1 Timothy 1:11', '1 Timothy', 1, 11, '&nbsp;دا تعليم د مبارک خُدائ پاک د جلالى زېرى په مطابق دے کوم چې هغۀ ما ته په حواله کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28575, '1 Timothy 1:12', '1 Timothy', 1, 12, '&nbsp;زۀ د خپل مالِک عيسىٰ مسيح شُکر کوم چا چې ما له طاقت راکړو او زۀ يې وفاداره وګڼلم او د خپل خِدمت دپاره يې مقرر کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28576, '1 Timothy 1:13', '1 Timothy', 1, 13, '&nbsp;اګر کۀ مخکښې زۀ کُفر غرونکے او عذاب ورکوونکے او ګستاخ سړے وم، خو په ما رحم وشو ځکه چې ما د بې‌ايمانۍ په حالت او په ناپوهۍ کښې دا کارونه کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28577, '1 Timothy 1:14', '1 Timothy', 1, 14, '&nbsp;او زمونږ د مالِک فضل په ما ډېر نازل شو د هغه ايمان او مينې په وجه چې د عيسىٰ مسيح په يووالى کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28578, '1 Timothy 1:15', '1 Timothy', 1, 15, '&nbsp;دا خبره رښتيا ده او په هر لحاظ د قبلولو جوګه ده، چې عيسىٰ مسيح ګناهګارانو له د خلاصون ورکولو دپاره دُنيا ته راغلو، چې په هغوئ ټولو کښې وړومبے زۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28579, '1 Timothy 1:16', '1 Timothy', 1, 16, '&nbsp;او په دې وجه په ما رحم وشو چې په ما وړومبى ګناه ګار کښې عيسىٰ مسيح خپل لوئ صبر څرګند کړى، او زۀ يې د هغه خلقو دپاره مثال وګرځولم څوک چې به په هغۀ د تل ژوندون دپاره ايمان راوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28580, '1 Timothy 1:17', '1 Timothy', 1, 17, '&nbsp;اوس دې د ازلى بادشاه، يعنې د ابدى او ناليدلى واحد خُدائ پاک عزت او جلال تل تر تله وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28581, '1 Timothy 1:18', '1 Timothy', 1, 18, '&nbsp;اے تيموتيوسه زما زويه، زۀ تا له دا هدايات درکوم د هغه پېشګويو په مطابق چې مخکښې ستا په حقله شوى دى، چې تۀ د هغې په مطابق ښۀ منډه ووهې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28582, '1 Timothy 1:19', '1 Timothy', 1, 19, '&nbsp;او په ايمان او په ښۀ ضمير قائم پاتې شئ. ځينو خلقو د خپل ضمير ونۀ منل، نو د هغوئ د ايمان بيړه غرقه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28583, '1 Timothy 1:20', '1 Timothy', 1, 20, '&nbsp;په هغوئ کښې هميناوس او سکندر شامل دى چې ما شېطان ته حواله کړل چې هغوئ دا زده کړى چې نور کُفر ونۀ غروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28584, '1 Timothy 2:1', '1 Timothy', 2, 1, '&nbsp;نو بيا زۀ د ټولو نه اول په تاسو دا زور راوړم چې خواستونه، دُعاګانې، شفاعت او د ټولو خلقو دپاره شُکر ګزارى کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28585, '1 Timothy 2:2', '1 Timothy', 2, 2, '&nbsp;د بادشاهانو او د ټولو لويو مرتبو خلقو دپاره دُعا کوئ، نو چې مونږ د آرام او پُراَمنه او د ديندارۍ او د عزت ژوند تېر کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28586, '1 Timothy 2:3', '1 Timothy', 2, 3, '&nbsp;داسې کول زمونږ د خلاصوونکى خُدائ پاک په نزد نېک او راضى کوونکى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28587, '1 Timothy 2:4', '1 Timothy', 2, 4, '&nbsp;هغه غواړى چې ټول خلق خلاصون ومومى او د حقيقت عِلم ورته حاصل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28588, '1 Timothy 2:5', '1 Timothy', 2, 5, '&nbsp;ځکه چې يو خُدائ پاک دے او د خُدائ پاک او د انسان تر مينځه مينځګړے هم يو دے، يعنې عيسىٰ مسيح، چې خپله بنى آدم دے', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28589, '1 Timothy 2:6', '1 Timothy', 2, 6, '&nbsp;چا چې خپل ځان د ټولو دپاره فديه کړو او په مناسب وخت کښې دا ثابته هم شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28590, '1 Timothy 2:7', '1 Timothy', 2, 7, '&nbsp;زۀ د دې دپاره بيان کوونکے او رسول او غېرو يهوديانو ته د ايمان او حقيقت خبرې ښوونکے مقرر شوم، دا زۀ دروغ نۀ وايم بلکې رښتيا وايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28591, '1 Timothy 2:8', '1 Timothy', 2, 8, '&nbsp;نو بيا زۀ غواړم چې په هر ځائ کښې دې خلق بغېر د غصې او بحث نه بې‌ګناه لاسونه اوچتوى او دُعا دې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28592, '1 Timothy 2:9', '1 Timothy', 2, 9, '&nbsp;او ښځې دې هم دغه شان خپل ځانونه د حيا، شرافت او پرهيزګارۍ په جامه کښې سمبالوى، او په کمڅو، سرو زرو او ملغلرو او قيمتى جامو سره دې ځانونه نۀ سنګاروى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28593, '1 Timothy 2:10', '1 Timothy', 2, 10, '&nbsp;بلکې په نېکو عملونو دې خپل ځان سنګاروى څنګه چې ديندارو ښځو له مناسب دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28594, '1 Timothy 2:11', '1 Timothy', 2, 11, '&nbsp;ښځې دې په خاموشۍ او په پوره تابعدارۍ سره زده کړه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28595, '1 Timothy 2:12', '1 Timothy', 2, 12, '&nbsp;او زۀ يوې ښځې ته اجازت نۀ ورکوم چې سړو ته تعليم ورکړى يا دې په هغوئ روب اچوى، بلکې هغه دې خاموشه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
