(28597, '1 Timothy 2:14', '1 Timothy', 2, 14, '&nbsp;او شېطان آدم دوکه نۀ کړو بلکې ښځه يې دوکه کړې وه او ګناهګاره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28598, '1 Timothy 2:15', '1 Timothy', 2, 15, '&nbsp;خو ښځې به د اولاد په پېدا کولو سره نجات حاصلوى، په دې شرط چې په ايمان، مينه او پاکيزګۍ کښې به د پرهيزګارۍ سره ژوند تېروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28599, '1 Timothy 3:1', '1 Timothy', 3, 1, '&nbsp;دا خبره رښتيا ده چې څوک د جماعت د مشر جوړېدلو خواهش کوى نو هغه د عزت کار غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28600, '1 Timothy 3:2', '1 Timothy', 3, 2, '&nbsp;نو په کار دى چې د جماعت مشر د اِلزام نه پاک، د يوې ښځې خاوند، پرهيزګار، شريف، د عزت قابل مېلمه دوست او د تعليم ورکولو لائق وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');